namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics including statistics." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, composition, and creative writing." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Exploration of past events, societies, and civilizations." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers and holds three patents in neural network optimization.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor", Bio = "Dr. Martinez focuses on abstract algebra and number theory. He received the Distinguished Teaching Award in 2023.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Prof. Sarah Williams", Title = "Professor", Bio = "Prof. Williams is an acclaimed novelist and literary critic with expertise in 20th-century American literature.", Email = "swilliams@university.edu" },
            new() { Id = 4, Name = "Dr. James Park", Title = "Assistant Professor", Bio = "Dr. Park researches quantum computing and condensed matter physics. He completed his postdoc at CERN.", Email = "jpark@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Nguyen", Title = "Professor", Bio = "Dr. Nguyen is a historian of early modern Europe with a focus on the social impact of the printing press.", Email = "enguyen@university.edu" },
            new() { Id = 6, Name = "Dr. Michael Brown", Title = "Associate Professor", Bio = "Dr. Brown specializes in software engineering and distributed systems. He spent 10 years in industry before joining academia.", Email = "mbrown@university.edu" },
            new() { Id = 7, Name = "Dr. Lisa Taylor", Title = "Assistant Professor", Bio = "Dr. Taylor works in applied statistics and data science, collaborating with the medical school on clinical trials.", Email = "ltaylor@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering programming fundamentals, data structures, and algorithmic thinking. Students will complete hands-on projects using Python.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Tech Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, CourseCode = "CS 301", Title = "Data Structures and Algorithms", Description = "In-depth study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Tech Hall 305", DepartmentId = 1, InstructorId = 6 },
            new() { Id = 3, CourseCode = "CS 450", Title = "Artificial Intelligence", Description = "Survey of AI techniques including search, knowledge representation, planning, machine learning, and natural language processing.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Hall 110", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 4, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to science and engineering.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Science Center 402", DepartmentId = 2, InstructorId = 2 },
            new() { Id = 5, CourseCode = "MATH 310", Title = "Probability and Statistics", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Science Center 310", DepartmentId = 2, InstructorId = 7, IsFeatured = true },
            new() { Id = 6, CourseCode = "ENG 101", Title = "Freshman Composition", Description = "Develops skills in expository and argumentative writing through close reading, discussion, and frequent writing assignments.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities 105", DepartmentId = 3, InstructorId = 3 },
            new() { Id = 7, CourseCode = "ENG 350", Title = "American Literature: 1900–Present", Description = "Survey of major American literary works from the 20th and 21st centuries, examining themes of identity, modernity, and social change.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Location = "Humanities 210", DepartmentId = 3, InstructorId = 3, IsFeatured = true },
            new() { Id = 8, CourseCode = "PHYS 201", Title = "Classical Mechanics", Description = "Newtonian mechanics, oscillations, wave motion, and an introduction to Lagrangian mechanics.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Physics Lab 101", DepartmentId = 4, InstructorId = 4 },
            new() { Id = 9, CourseCode = "PHYS 410", Title = "Quantum Mechanics", Description = "Foundations of quantum theory including wave functions, the Schrödinger equation, angular momentum, and spin.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Physics Lab 203", DepartmentId = 4, InstructorId = 4 },
            new() { Id = 10, CourseCode = "HIST 101", Title = "World History to 1500", Description = "A survey of major civilizations, cultures, and events from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", Location = "Liberal Arts 300", DepartmentId = 5, InstructorId = 5 },
            new() { Id = 11, CourseCode = "HIST 320", Title = "Renaissance and Reformation", Description = "Examines the cultural, political, and religious transformations of Europe from the 14th to 17th centuries.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Liberal Arts 215", DepartmentId = 5, InstructorId = 5 },
            new() { Id = 12, CourseCode = "CS 210", Title = "Software Engineering", Description = "Principles of software development including requirements analysis, design patterns, testing, and agile methodologies. Team-based project throughout the semester.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Tech Hall 201", DepartmentId = 1, InstructorId = 6, IsFeatured = true },
        };
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        IEnumerable<Course> query = _courses;

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.CourseCode).ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).OrderBy(c => c.CourseCode).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request) => _enrollments.Add(request);
}

